1	/**
2	 * `@pantoken/web-components` — framework-agnostic custom elements for Instructure UI.
3	 *
4	 * Registers `<instui-icon>` (glyphs from `@pantoken/icons`) plus a set of token-styled elements that
5	 * wrap the `@pantoken/components` CSS: `<instui-button>`, `<instui-alert>`, `<instui-badge>`,
6	 * `<instui-pill>`, `<instui-tag>`, `<instui-avatar>`, `<instui-spinner>`, `<instui-progress>`,
7	 * `<instui-progress-circle>`, `<instui-metric>`, `<instui-rating>`, `<instui-icon-button>`,
8	 * `<instui-toggle-button>`, `<instui-truncate>`, `<instui-img>`, `<instui-side-nav-bar>`,
9	 * `<instui-tree-browser>`, and `<instui-tooltip>`, plus the behavioral elements
10	 * `<instui-modal>` (a real `<dialog>` driven by its `open` attribute), the native popovers
11	 * `<instui-context-view>`, `<instui-popover>`, and `<instui-tray>`, `<instui-in-place-edit>` (a
12	 * click-to-edit field that commits on Enter/blur and reverts on Escape), `<instui-drilldown>` (a
13	 * stateful multi-level menu), `<instui-pages>` (one-panel-at-a-time nav via the View Transitions API),
14	 * `<instui-drawer-layout>` (a collapsible, drag-resizable side panel), the interactive
15	 * `<instui-calendar>` (a month grid navigated with the Invoker Commands API), and the pickers
16	 * `<instui-date-input>` and `<instui-date-time-input>` (a field plus a calendar-dropdown popover).
17	 * Each renders the matching `.instui-*` markup into its shadow root with the component stylesheet
18	 * inlined, so the look is exactly `@pantoken/components`
19	 * with nothing to import but this module. Tokens are inherited custom properties, so they pierce the
20	 * shadow boundary — load `@pantoken/css` (or any pantoken token sheet) in the document to color them.
21	 * The elevation scale and focus-outline system live in the components/base layer rather than the token
22	 * sheet, so {@link register} injects them at `:root` ({@link foundationCss}) — shadows inherit them, and
23	 * elevation/focus work with only the token sheet loaded.
24	 *
25	 * The module is Node-safe: element classes are defined inside {@link register}, a no-op when there
26	 * is no DOM, so importing this package during SSR or a build never touches `HTMLElement`.
27	 *
28	 * Each element lives in its own documented file under `elements/`, exporting an
29	 * {@link ElementDefinition}; `elements/index.ts` lists them in registration order as `DEFINITIONS`.
30	 * {@link register} builds one prefix-aware {@link RegisterContext} and hands it to each definition.
31	 *
32	 * @module
33	 * @alpha
34	 */
35	import { elevationDeclarations, focusOutlineDeclarations } from "@pantoken/components";
36	import { resolve as pantokenResolve } from "@pantoken/icons";
37	import type { IconResolver } from "@pantoken/model";
38	import { DEFINITIONS } from "./elements/index.ts";
39	import type { CommandEventish, ElementRegistry, RegisterContext } from "./lib/context.ts";
40	import { applySpacing, frag } from "./lib/helpers.ts";
41	
42	// ── Public types ──────────────────────────────────────────────────────────────
43	export type {
44	  CommandEventish,
45	  ElementDefinition,
46	  ElementRegistry,
47	  RegisterContext,
48	} from "./lib/context.ts";
49	
50	// ── Element definitions ─────────────────────────────────────────────────────────
51	export { DEFINITIONS } from "./elements/index.ts";
52	export { alert } from "./elements/alert.ts";
53	export { avatar } from "./elements/avatar.ts";
54	export { badge } from "./elements/badge.ts";
55	export { button } from "./elements/button.ts";
56	export { calendar } from "./elements/calendar.ts";
57	export { contextView } from "./elements/context-view.ts";
58	export { dateInput } from "./elements/date-input.ts";
59	export { dateTimeInput } from "./elements/date-time-input.ts";
60	export { drawerLayout } from "./elements/drawer-layout.ts";
61	export { drilldown } from "./elements/drilldown.ts";
62	export { icon } from "./elements/icon.ts";
63	export { iconButton } from "./elements/icon-button.ts";
64	export { img } from "./elements/img.ts";
65	export { inPlaceEdit } from "./elements/in-place-edit.ts";
66	export { metric } from "./elements/metric.ts";
67	export { modal } from "./elements/modal.ts";
68	export { pages } from "./elements/pages.ts";
69	export { pill } from "./elements/pill.ts";
70	export { popover } from "./elements/popover.ts";
71	export { progress } from "./elements/progress.ts";
72	export { progressCircle } from "./elements/progress-circle.ts";
73	export { rating } from "./elements/rating.ts";
74	export { sideNavBar } from "./elements/side-nav-bar.ts";
75	export { spinner } from "./elements/spinner.ts";
76	export { tag } from "./elements/tag.ts";
77	export { toggleButton } from "./elements/toggle-button.ts";
78	export { tooltip } from "./elements/tooltip.ts";
79	export { tray } from "./elements/tray.ts";
80	export { treeBrowser } from "./elements/tree-browser.ts";
81	export { truncate } from "./elements/truncate.ts";
