83	/** The default tag prefix, mirroring the CSS layer — `<instui-icon>`, `.instui-button`, etc. */
84	export const DEFAULT_PREFIX = "instui";
85	
86	/**
87	 * The base (unprefixed) element names this package registers. {@link register} mints a tag per name
88	 * under its `prefix` option — `icon` → `<instui-icon>` by default, or `<x-icon>` for `{ prefix: "x" }`.
89	 * A prefix is always applied (a custom-element name must contain a hyphen), so an empty or nullish prefix
90	 * falls back to the default `instui`.
91	 */
92	export const ELEMENTS = [
93	  "icon",
94	  "button",
95	  "alert",
96	  "badge",
97	  "pill",
98	  "tag",
99	  "avatar",
100	  "spinner",
101	  "progress",
102	  "metric",
103	  "rating",
104	  "progress-circle",
105	  "icon-button",
106	  "toggle-button",
107	  "truncate",
108	  "img",
109	  "side-nav-bar",
110	  "tree-browser",
111	  "calendar",
112	  "tooltip",
113	  "modal",
114	  "context-view",
115	  "popover",
116	  "tray",
117	  "in-place-edit",
118	  "drilldown",
119	  "pages",
120	  "drawer-layout",
121	  "date-input",
122	  "date-time-input",
123	] as const;
124	
125	/**
126	 * Resolve an icon name to inline SVG (empty string when unknown). Pure — the element renders it.
127	 *
128	 * @param name - The icon name (e.g. `arrow-left`).
129	 * @param resolve - The resolver (defaults to the built-in pantoken icon set).
130	 *
131	 * @example
132	 * ```ts
133	 * import { iconSvg } from "@pantoken/web-components";
134	 *
135	 * const svg = iconSvg("arrow-left"); // "<svg …>…</svg>", or "" when unknown
136	 * ```
137	 */
138	export function iconSvg(name: string, resolve: IconResolver = pantokenResolve): string {
139	  return resolve(name)?.svg ?? "";
140	}
141	
142	/** The id of the `<style>` {@link register} injects, so the foundation is added at most once. */
143	const FOUNDATION_STYLE_ID = "pantoken-foundation";
144	
145	/**
146	 * The `:root` custom-property block that bundles the elevation scale (`--instui-elevation-*`) and the
147	 * focus-outline system (`--instui-focus-outline-*`). The component CSS references these, but the token
148	 * sheet (`@pantoken/css`) doesn't carry them — they live in the components/base layer. Because custom
149	 * properties pierce the shadow boundary, declaring them once at `:root` makes every element's shadow
150	 * inherit them, so shadows, focus rings, etc. work with nothing loaded but this module + a token sheet.
151	 * {@link register} injects it client-side; export it too so SSR can inline it up front.
152	 *
153	 * @returns A `:root { … }` CSS string.
154	 *
155	 * @example
156	 * ```ts
157	 * import { foundationCss } from "@pantoken/web-components";
158	 * // SSR: `<style>${foundationCss()}</style>` in <head>.
159	 * ```
160	 */
161	export function foundationCss(): string {
162	  const decls = [...elevationDeclarations(), ...focusOutlineDeclarations()]
163	    .map(([name, value]) => `  ${name}: ${value};`)
164	    .join("\n");
165	  return `:root {\n${decls}\n}`;
166	}
167	
168	/** An element ctor with the optional custom-element lifecycle hooks the spacing mixin composes over. */
169	type LifecycleElementCtor = new (...args: never[]) => HTMLElement & {
170	  connectedCallback?(): void;
171	  disconnectedCallback?(): void;
172	};
173	
174	/**
175	 * Compose the universal spacing behaviour over an element constructor: after the element's own
176	 * `connectedCallback`, and on any later attribute change, apply the `margin`/`padding` shorthands and
177	 * per-side `margin-<side>`/`padding-<side>` attributes to the host ({@link applySpacing}). {@link register}
178	 * wraps every element with this, so InstUI-/CSS-style spacing works on all of them with no per-element code.
179	 *
180	 * @param Ctor - The element constructor to wrap.
181	 * @returns A subclass that adds the spacing behaviour.
182	 */
183	function withSpacing(Ctor: LifecycleElementCtor): CustomElementConstructor {
184	  const Spaced = class extends Ctor {
185	    #spacingObserver: MutationObserver | undefined;
186	    connectedCallback(): void {
187	      super.connectedCallback?.();
188	      applySpacing(this);
189	      this.#spacingObserver = new MutationObserver(() => {
190	        applySpacing(this);
191	      });
192	      this.#spacingObserver.observe(this, { attributes: true });
193	    }
194	    disconnectedCallback(): void {
195	      super.disconnectedCallback?.();
196	      this.#spacingObserver?.disconnect();
197	    }
198	  };
199	  return Spaced as unknown as CustomElementConstructor;
200	}
201	
202	/**
203	 * Register the pantoken custom elements. No-op when there is no DOM (SSR / build), so this module
204	 * is safe to import anywhere.
205	 *
206	 * @param target - The registry to define into (defaults to `globalThis.customElements`).
207	 * @param options - `prefix` sets the tag prefix, mirroring the CSS layer: pass a non-empty string like
208	 *   `x` for `<x-icon>`. A prefix is always applied (a custom-element name must contain a hyphen), so an
209	 *   omitted, empty, or nullish prefix falls back to the default `instui` (`<instui-icon>`).
210	 *
211	 * @example
212	 * ```ts
213	 * import { register } from "@pantoken/web-components";
214	 * import "@pantoken/css"; // defines the --instui-* custom properties the elements read
215	 *
216	 * register(); // <instui-button>, <instui-icon>, …
217	 * register(customElements, { prefix: "x" }); // <x-button>, <x-icon>, …
218	 * ```
219	 */
220	export function register(
221	  target: ElementRegistry | undefined = globalThis.customElements,
222	  options: { prefix?: string | null } = {},
223	): void {
224	  if (!target || typeof HTMLElement === "undefined") return;
225	
226	  // Bundle the elevation + focus-outline custom properties at `:root` once, so every shadow inherits
227	  // them (they aren't in the token sheet). Skipped without a DOM (e.g. the registry-only test path).
228	  if (
229	    typeof document !== "undefined" &&
230	    document.head &&
231	    !document.getElementById(FOUNDATION_STYLE_ID)
232	  ) {
233	    const style = document.createElement("style");
234	    style.id = FOUNDATION_STYLE_ID;
235	    style.textContent = foundationCss();
236	    document.head.append(style);
237	  }
238	
239	  // Tag prefix: a valid non-empty string overrides the default; anything else (empty, whitespace, null,
240	  // omitted) falls back to `instui`. A prefix is always applied because a custom-element name MUST contain
241	  // a hyphen — `<icon>` is invalid, `<instui-icon>`/`<x-icon>` are not. The inlined `.instui-*` CSS classes
242	  // are an internal detail and are NOT affected by this — only the custom-element tag name.
243	  const prefix =
244	    typeof options.prefix === "string" && options.prefix.trim() !== ""
245	      ? options.prefix
246	      : DEFAULT_PREFIX;
247	  const tag = (base: string): string => `${prefix}-${base}`;
248	  // Route every internal `registry.get`/`define` (all keyed on the canonical `instui-<base>` names)
249	  // through the active prefix.
250	  const host = target;
251	  const registry: ElementRegistry = {
252	    get: (name) => host.get(tag(name.replace(/^instui-/u, ""))),
253	    define: (name, ctor) => {
254	      const resolved = tag(name.replace(/^instui-/u, ""));
255	      // Wrap every element with the shared spacing mixin, so `margin`/`padding` (+ per-side) work
256	      // universally — no per-element code needed.
257	      if (!host.get(resolved)) host.define(resolved, withSpacing(ctor));
258	    },
259	  };
260	
261	  // A shadow-DOM `<button>` can invoke a light-DOM `[popover]` (or dispatch a command) only through the
262	  // IDL properties — the `popovertarget`/`commandfor` *attributes* resolve their id in the button's own
263	  // tree scope (the shadow root), so they never find a light-DOM target. `syncInvoker` mirrors the host's
264	  // invoker attributes onto the inner button's IDL properties, resolving the id against the host's root.
265	  type InvokerButton = HTMLButtonElement & {
266	    popoverTargetElement?: Element | null;
267	    popoverTargetAction?: string;
268	    commandForElement?: Element | null;
269	    command?: string;
270	  };
271	  const syncInvoker = (host: HTMLElement): void => {
272	    const btn = host.shadowRoot?.querySelector("button") as InvokerButton | null;
273	    if (!btn) return;
274	    const root = host.getRootNode() as Document | ShadowRoot;
275	    const byId = (id: string): Element | null =>
276	      typeof root.getElementById === "function" ? root.getElementById(id) : null;
277	    const popoverTarget = host.getAttribute("popovertarget");
278	    if (popoverTarget !== null) {
279	      btn.popoverTargetElement = byId(popoverTarget);
280	      btn.popoverTargetAction = host.getAttribute("popovertargetaction") ?? "toggle";
281	    }
282	    const commandFor = host.getAttribute("commandfor");
283	    const command = host.getAttribute("command");
284	    if (commandFor !== null && command !== null) {
285	      btn.commandForElement = byId(commandFor);
286	      btn.command = command;
287	    }
288	  };
289	
290	  /**
291	   * Define a shadow-DOM element: `<style>:host{display}css</style>` + markup from `render(host)`.
292	   * The `:host` display is explicit because a custom element defaults to `display: inline`, which
293	   * would collapse internal `width: 100%` (e.g. the progress bar). Pass `invoker: true` when the
294	   * rendered markup is a `<button>` that should drive native `popovertarget`/`command` targets.
295	   */
296	  const wrapper = (
297	    tag: string,
298	    css: string,
299	    render: (host: HTMLElement) => string,
300	    { display = "inline-block", invoker = false }: { display?: string; invoker?: boolean } = {},
301	  ): void => {
302	    if (registry.get(tag)) return;
303	    registry.define(
304	      tag,
305	      class extends HTMLElement {
306	        static observedAttributes = [
307	          "variant",
308	          "size",
309	          "shape",
310	          "value",
311	          "max",
312	          "label",
313	          "pressed",
314	          "lines",
315	          "placement",
316	          "minimized",
317	          "constrain",
318	          "src",
319	          "alt",
320	          "tip",
321	          "has-shadow",
322	          "popovertarget",
323	          "popovertargetaction",
324	          "command",
325	          "commandfor",
326	        ];
327	        constructor() {
328	          super();
329	          this.attachShadow({ mode: "open" });
330	        }
331	        connectedCallback(): void {
332	          this.paint();
333	          if (invoker) {
334	            // Re-resolve the target on each interaction: an id can point forward to an element parsed
335	            // after this button, and the target may be swapped at runtime. `requestAnimationFrame`
336	            // catches the initial forward reference once the document has finished parsing.
337	            const sync = (): void => syncInvoker(this);
338	            this.addEventListener("pointerdown", sync);
339	            this.addEventListener("keydown", sync);
340	            if (typeof requestAnimationFrame === "function") requestAnimationFrame(sync);
341	          }
342	        }
343	        attributeChangedCallback(): void {
344	          this.paint();
345	        }
346	        paint(): void {
347	          if (this.shadowRoot) {
348	            this.shadowRoot.innerHTML = `<style>:host{display:${display}}${css}</style>${render(this)}`;
349	            if (invoker) syncInvoker(this);
350	          }
351	        }
352	      },
353	    );
354	  };
355	
356	  // The shadow-DOM CSS is built with the default `instui` prefix so it matches the `instui-*` markup
357	  // in each element (the builders drop the prefix on a falsy value).
358	  const I = { prefix: "instui" } as const;
359	
360	  /** A `.instui-<name>` class with a single `-color-<variant>` key-value modifier from `variant`. */
361	  const variantClass = (name: string, host: HTMLElement): string => {
362	    const variant = frag(host.getAttribute("variant"));
363	    return variant ? `instui-${name} -color-${variant}` : `instui-${name}`;
364	  };
365	
366	  // The calendar and date picker drive navigation with the Invoker Commands API. `onCommand` routes a
367	  // target's `command` events to a handler; where the API is unavailable it delegates clicks on the
368	  // target's own `command`/`commandfor` buttons instead, so the buttons keep working everywhere.
369	  const INVOKER_SUPPORTED =
370	    typeof HTMLButtonElement !== "undefined" && "command" in HTMLButtonElement.prototype;
371	  const onCommand = (
372	    target: HTMLElement,
373	    handler: (command: string, source: Element | null) => void,
374	  ): void => {
375	    target.addEventListener("command", (event) => {
376	      const ce = event as CommandEventish;
377	      handler(ce.command, ce.source);
378	    });
379	    if (!INVOKER_SUPPORTED) {
380	      // Fallback for browsers without the API: delegate clicks across the target's tree — its shadow root
381	      // for an internal grid, or the document for a light-DOM host — to the same handler, matching on
382	      // `commandfor`, so `command` buttons keep working wherever they live.
383	      const scope = target.getRootNode() as Document | ShadowRoot;
384	      scope.addEventListener("click", (event) => {
385	        const el = event.target instanceof Element ? event.target : null;
386	        const button = el?.closest<HTMLButtonElement>("button[command][commandfor]");
387	        if (button?.getAttribute("commandfor") === target.id) {
388	          handler(button.getAttribute("command") ?? "", button);
389	        }
390	      });
391	    }
392	  };
393	
394	  const ctx: RegisterContext = {
395	    registry,
396	    tag,
397	    I,
398	    invokerSupported: INVOKER_SUPPORTED,
399	    onCommand,
400	    wrapper,
401	    variantClass,
402	    iconSvg,
403	  };
404	
405	  for (const def of DEFINITIONS) def.define(ctx);
406	}
407	
408	// Auto-register in the browser; a no-op everywhere else.
409	register();
