1	/**
2	 * Shared types for the web-components registry: the structural registry adapter, the Invoker
3	 * Commands event shape, and the {@link RegisterContext}/{@link ElementDefinition} contract that lets
4	 * every element live in its own file yet register through one shared, prefix-aware pipeline.
5	 *
6	 * @module
7	 */
8	
9	/** A minimal structural type for a custom-element registry (the DOM's `customElements`). */
10	export interface ElementRegistry {
11	  get(name: string): unknown;
12	  define(name: string, ctor: CustomElementConstructor): void;
13	}
14	
15	/** The `command`/`source` shape of an Invoker Commands `CommandEvent` (not yet in the DOM lib types). */
16	export interface CommandEventish extends Event {
17	  command: string;
18	  source: Element | null;
19	}
20	
21	/**
22	 * The shared state a `register()` call builds once and threads to every {@link ElementDefinition}.
23	 * It carries the prefix-aware registry adapter, the `tag()` helper for nested markup, the CSS-class
24	 * prefix `I`, the Invoker Commands support flag + router, and the `wrapper`/`variantClass`/`iconSvg`
25	 * factories the simple elements share.
26	 */
27	export interface RegisterContext {
28	  /** The scoped registry: rewrites `instui-<base>` → the active-prefix tag on `get`/`define`. */
29	  registry: ElementRegistry;
30	  /** Map a base name to the active-prefix tag (for nested markup, `querySelector`, `tagName`). */
31	  tag: (base: string) => string;
32	  /** The CSS-class prefix for the inlined component sheets — always `instui`, separate from the tag prefix. */
33	  I: { readonly prefix: "instui" };
34	  /** Whether the browser supports the Invoker Commands API (`command`/`commandfor`). */
35	  invokerSupported: boolean;
36	  /** Route a target's `command` events (or a click fallback) to a handler. */
37	  onCommand: (
38	    target: HTMLElement,
39	    handler: (command: string, source: Element | null) => void,
40	  ) => void;
41	  /** Define a shadow-DOM element: `<style>:host{display}css</style>` + markup from `render(host)`.
42	   * `invoker: true` forwards the host's `popovertarget`/`command` to the inner `<button>` (IDL). */
43	  wrapper: (
44	    tag: string,
45	    css: string,
46	    render: (host: HTMLElement) => string,
47	    options?: { display?: string; invoker?: boolean },
48	  ) => void;
49	  /** Build a `.instui-<name>` class with an optional `-color-<variant>` modifier from `variant`. */
50	  variantClass: (name: string, host: HTMLElement) => string;
51	  /** Resolve an icon name to inline SVG (empty string when unknown). */
52	  iconSvg: (name: string) => string;
53	}
54	
55	/** One registered custom element: its base tag name plus a `define` that registers it via the context. */
56	export interface ElementDefinition {
57	  /** The base tag name, e.g. `button` (minted to `<instui-button>`/`<x-button>` by the active prefix). */
58	  readonly name: string;
59	  /** Register the element into `ctx.registry`, using only the shared, prefix-aware helpers. */
60	  define(ctx: RegisterContext): void;
61	}
62

1	/**
2	 * The registry of element definitions. {@link DEFINITIONS} lists them in the canonical registration
3	 * order (load-bearing: nesting elements like `date-input` assume `calendar` and `date-time-input`
4	 * assume `date-input` are defined, and the parity test asserts this exact order). `register()` in the
5	 * package barrel builds the shared context once and calls each definition's `define`.
6	 *
7	 * @module
8	 */
9	import type { ElementDefinition } from "../lib/context.ts";
10	import { alert } from "./alert.ts";
11	import { avatar } from "./avatar.ts";
12	import { badge } from "./badge.ts";
13	import { button } from "./button.ts";
14	import { calendar } from "./calendar.ts";
15	import { contextView } from "./context-view.ts";
16	import { dateInput } from "./date-input.ts";
17	import { dateTimeInput } from "./date-time-input.ts";
18	import { drawerLayout } from "./drawer-layout.ts";
19	import { drilldown } from "./drilldown.ts";
20	import { icon } from "./icon.ts";
21	import { iconButton } from "./icon-button.ts";
22	import { img } from "./img.ts";
23	import { inPlaceEdit } from "./in-place-edit.ts";
24	import { metric } from "./metric.ts";
25	import { modal } from "./modal.ts";
26	import { pages } from "./pages.ts";
27	import { pill } from "./pill.ts";
28	import { popover } from "./popover.ts";
29	import { progress } from "./progress.ts";
30	import { progressCircle } from "./progress-circle.ts";
31	import { rating } from "./rating.ts";
32	import { sideNavBar } from "./side-nav-bar.ts";
33	import { spinner } from "./spinner.ts";
34	import { tag } from "./tag.ts";
35	import { toggleButton } from "./toggle-button.ts";
36	import { tooltip } from "./tooltip.ts";
37	import { tray } from "./tray.ts";
38	import { treeBrowser } from "./tree-browser.ts";
39	import { truncate } from "./truncate.ts";
40	
41	/**
42	 * Every element definition, in the canonical registration order. The order is load-bearing:
43	 * `date-input` renders a nested `calendar` and `date-time-input` renders a nested `date-input`, and
44	 * the `ELEMENTS` tuple / the register-order test both derive from this list.
45	 */
46	export const DEFINITIONS: readonly ElementDefinition[] = [
47	  icon,
48	  button,
49	  alert,
50	  badge,
