1	/**
2	 * `@pantoken/utils` — shared, upstream-free helpers used across the pantoken packages: the token
3	 * reference resolver (with `light-dark()` handling), the two token regexes (typed via `arkregex`),
4	 * kebab→camel case, hex-colour parsing, and the generic token→utility-class emitters
5	 * ({@link colorUtilitiesCss}, {@link tokenUtilitiesCss}) that both `@pantoken/components` (semantic
6	 * tier) and `@pantoken/plugin-primitives` (raw-palette tier) build on. Depends only on
7	 * `@pantoken/model` (types) + `arkregex`, so any package can use it without pulling the GitHub-only
8	 * upstream.
9	 *
10	 * @module
11	 * @beta
12	 */
13	import { regex } from "arkregex";
14	import type { Token } from "@pantoken/model";
15	
16	/** The colour mode to collapse `light-dark()` to. */
17	export type Mode = "light" | "dark";
18	
19	// Pattern sources (also used to build fresh regexes where reuse would be unsafe).
20	const VAR_SOURCE = "var\\(\\s*(--[\\w-]+)[^)]*\\)";
21	const LIGHT_DARK_SOURCE = "^light-dark\\(\\s*(.+?)\\s*,\\s*(.+?)\\s*\\)$";
22	
23	/** A `var(--custom-prop)` reference (optional fallback); capture group 1 is the property name. */
24	export const VAR_RE = regex(VAR_SOURCE, "g");
25	/** A `light-dark(<light>, <dark>)` value; capture groups 1 and 2 are the two branches. */
26	export const LIGHT_DARK_RE = regex(LIGHT_DARK_SOURCE);
27	
28	const MAX_DEPTH = 12;
29	
30	/** Options for {@link makeResolver}. */
31	export interface ResolveOptions {
32	  /** Collapse `light-dark()` to this branch; omit to keep `light-dark()` intact. */
33	  mode?: Mode;
34	  /** Tokens that override the base set (win on name collisions, e.g. a caller's IR over a theme). */
35	  overrides?: readonly Token[];
36	}
37	
38	/**
39	 * Build a resolver that expands `var(--x)` references to concrete leaf values against `base` (plus
40	 * any `overrides`). With `mode` it collapses `light-dark()` to that branch; without, it leaves
41	 * `light-dark()` in place.
42	 *
43	 * @param base - The token set to resolve references against.
44	 * @param options - {@link ResolveOptions}.
45	 * @returns A function that resolves a value string.
46	 *
47	 * @example Expand a reference chain to its concrete leaf
48	 * ```ts
49	 * import { makeResolver } from "@pantoken/utils";
50	 * import type { Token } from "@pantoken/model";
51	 *
52	 * const ir: Token[] = [
53	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
54	 *   { name: "--instui-brand", syntax: "*", inherits: true, value: "var(--instui-leaf)" },
55	 * ];
56	 *
57	 * const resolve = makeResolver(ir);
58	 * resolve("var(--instui-brand)"); // → "#0374B5"
59	 * ```
60	 *
61	 * @example Collapse light-dark() with a mode, or keep it without one
62	 * ```ts
63	 * import { makeResolver } from "@pantoken/utils";
64	 * import type { Token } from "@pantoken/model";
65	 *
66	 * const ir: Token[] = [
67	 *   { name: "--instui-bg", syntax: "*", inherits: true, value: "light-dark(#fff, #000)" },
68	 * ];
69	 *
70	 * makeResolver(ir)("var(--instui-bg)");                 // → "light-dark(#fff, #000)"
71	 * makeResolver(ir, { mode: "light" })("var(--instui-bg)"); // → "#fff"
72	 * makeResolver(ir, { mode: "dark" })("var(--instui-bg)");  // → "#000"
73	 * ```
74	 *
75	 * @example Layer overrides that win on name collisions
76	 * ```ts
77	 * import { makeResolver } from "@pantoken/utils";
78	 * import type { Token } from "@pantoken/model";
79	 *
80	 * const ir: Token[] = [
81	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
82	 *   { name: "--instui-brand", syntax: "*", inherits: true, value: "var(--instui-leaf)" },
83	 * ];
84	 * const overrides: Token[] = [
85	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#000" },
86	 * ];
87	 *
88	 * makeResolver(ir, { overrides })("var(--instui-brand)"); // → "#000"
89	 * ```
90	 */
91	export function makeResolver(
92	  base: readonly Token[],
93	  options: ResolveOptions = {},
94	): (value: string) => string {
95	  const map = new Map(base.map((t) => [t.name, t.value]));
96	  for (const t of options.overrides ?? []) map.set(t.name, t.value);
97	
98	  const pickMode = (value: string): string => {
99	    if (!options.mode) return value;
100	    const m = LIGHT_DARK_RE.exec(value.trim());
101	    return m ? (options.mode === "light" ? m[1] : m[2]) : value;
102	  };
103	
104	  const expand = (value: string, depth: number): string => {
105	    const picked = pickMode(value);
106	    if (depth >= MAX_DEPTH || !picked.includes("var(")) return picked;
107	    // Fresh regex per call — a shared /g regex would corrupt its lastIndex across these recursive
108	    // replace() calls.
109	    return picked.replace(new RegExp(VAR_SOURCE, "g"), (whole, name: string) => {
110	      const inner = map.get(name);
111	      return inner === undefined ? whole : expand(inner, depth + 1);
112	    });
113	  };
114	
115	  return (value) => expand(value, 0);
116	}
117	
118	/**
119	 * Resolve every token's value against the set (see {@link makeResolver}), keyed by name.
120	 *
121	 * @example Resolve a whole IR to a name → value map
122	 * ```ts
123	 * import { resolveTokens } from "@pantoken/utils";
124	 * import type { Token } from "@pantoken/model";
125	 *
126	 * const ir: Token[] = [
127	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
128	 *   { name: "--instui-brand", syntax: "*", inherits: true, value: "var(--instui-leaf)" },
129	 *   { name: "--instui-bg", syntax: "*", inherits: true, value: "light-dark(#fff, #000)" },
130	 * ];
131	 *
132	 * const byName = resolveTokens(ir, { mode: "dark" });
133	 * byName.get("--instui-brand"); // → "#0374B5"
134	 * byName.get("--instui-bg");    // → "#000"
135	 * ```
136	 */
137	export function resolveTokens(
138	  base: readonly Token[],
139	  options: ResolveOptions = {},
140	): Map<string, string> {
141	  const resolve = makeResolver(base, options);
142	  return new Map(base.map((t) => [t.name, resolve(t.value)]));
143	}
