145	/**
146	 * Convert a kebab-case string to camelCase (`color-background-brand` → `colorBackgroundBrand`).
147	 *
148	 * @example
149	 * ```ts
150	 * import { camelCase } from "@pantoken/utils";
151	 *
152	 * camelCase("color-background-brand"); // → "colorBackgroundBrand"
153	 * ```
