167	/**
168	 * Parse `#rgb`, `#rrggbb`, or `#rrggbbaa` to {@link Rgba}; returns `undefined` otherwise.
169	 *
170	 * @example
171	 * ```ts
172	 * import { parseHexColor } from "@pantoken/utils";
173	 *
174	 * parseHexColor("#fff");      // → { r: 255, g: 255, b: 255, a: 1 }
175	 * parseHexColor("#0374B5");   // → { r: 3, g: 116, b: 181, a: 1 }
176	 * parseHexColor("#00000080"); // → { r: 0, g: 0, b: 0, a: 0.5019… }
