183	  let h = m[1];
184	  if (h.length === 3) h = h.replace(/(.)/g, "$1$1");
185	  return {
186	    r: Number.parseInt(h.slice(0, 2), 16),
187	    g: Number.parseInt(h.slice(2, 4), 16),
188	    b: Number.parseInt(h.slice(4, 6), 16),
189	    a: h.length === 8 ? Number.parseInt(h.slice(6, 8), 16) / 255 : 1,
190	  };
191	}
