212	/**
213	 * The set of token names an IR defines.
214	 *
215	 * @example
216	 * ```ts
217	 * import { tokenNames } from "@pantoken/utils";
218	 * import type { Token } from "@pantoken/model";
219	 *
220	 * const ir: Token[] = [
221	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
222	 * ];
