235	 * @param text - The generated output.
236	 * @param ir - The source token IR.
237	 * @returns The unknown token names.
238	 *
239	 * @example
240	 * ```ts
241	 * import { unknownReferences } from "@pantoken/utils";
242	 * import type { Token } from "@pantoken/model";
243	 *
244	 * const ir: Token[] = [
245	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
246	 * ];
247	 *
248	 * unknownReferences("--x: var(--instui-leaf); --y: var(--instui-gone);", ir);
