263	 * @param css - The generated stylesheet.
264	 * @returns The dangling reference names.
265	 *
266	 * @example
267	 * ```ts
268	 * import { danglingReferences } from "@pantoken/utils";
269	 *
270	 * // Self-contained: the referenced property is also defined here.
271	 * danglingReferences("@property --instui-a {} .b { color: var(--instui-a); }"); // → []
272	 *
273	 * // Dangling: `--instui-b` is referenced but never defined.
274	 * danglingReferences(
275	 *   ":root { --instui-a: red; } .b { color: var(--instui-a); background: var(--instui-b); }",
276	 * ); // → ["--instui-b"]
277	 * ```
278	 */
279	export function danglingReferences(css: string): string[] {
280	  const referenced = new Set([...css.matchAll(/var\(\s*(--instui-[\w-]+)/g)].map((m) => m[1]));
281	  const defined = new Set<string>();
282	  for (const m of css.matchAll(/@property\s+(--instui-[\w-]+)/g)) defined.add(m[1]);
283	  for (const m of css.matchAll(/(--instui-[\w-]+)\s*:/g)) defined.add(m[1]);
