290	// live here (not in a format) so the primitive tier doesn't have to reach up into the component library.
291	
292	/** Options shared by the utility-class emitters. */
293	export interface UtilityOptions {
294	  /**
295	   * The class prefix. Any truthy string namespaces every class (`"instui"` → `.instui-bg-…`); any
296	   * falsy value (`null`/`undefined`/`""`) drops the prefix entirely (`.bg-…`).
297	   */
298	  prefix?: string | null;
299	}
