301	/** The semantic colour token names (without the `--instui-color-<family>-` prefix) per family. */
302	export interface ColorUtilityNames {
303	  background: readonly string[];
304	  text: readonly string[];
305	  stroke: readonly string[];
306	}
307	
308	/**
309	 * Build the semantic-colour utility stylesheet: `.<prefix>-bg-<name>` (background),
310	 * `.<prefix>-fg-<name>` (text colour), `.<prefix>-border-<name>` (border colour), one per semantic
311	 * colour token. Overrides are therefore only ever token-valid — no primitives, no arbitrary hex. Pass
312	 * the token names per family (e.g. from `@pantoken/tokens`).
313	 *
314	 * @param names - {@link ColorUtilityNames}.
315	 * @param options - {@link UtilityOptions}.
316	 * @returns The CSS string.
317	 *
318	 * @demo self:color-utilities
319	 */
320	export function colorUtilitiesCss(names: ColorUtilityNames, options: UtilityOptions = {}): string {
321	  const prefix = options.prefix || "";
322	  const p = prefix ? `${prefix}-` : "";
323	  const emit = (family: string, util: string, prop: string, list: readonly string[]): string =>
324	    list
