/** Options for {@link toCss}. */
export interface ToCssOptions {
  /** The selector scoped declarations are emitted under (default `":root"`). */
  scope?: string;
  /** Plugins whose `css` hooks run after the base CSS is built (default: none). */
  plugins?: readonly PantokenPlugin[];
  /**
   * Lean mode: emit concrete tokens as plain `:root` declarations instead of typed `@property`
   * registrations. This drops the large `@property` block (~86% of the default sheet is icon
   * `<image>` registrations), shrinking the sheet for CDN/embed delivery. Tokens matched by
   * {@link ToCssOptions.keepTyped} still register as `@property`. Default `false` (typed).
   */
  lean?: boolean;
  /**
   * In lean mode, a predicate for custom-property names that must keep their `@property`
   * registration — e.g. a value type that an animation/transition interpolates (only meaningful for
   * concrete, non-contextual values; a `var()`/`light-dark()` value can never be a valid `@property`).
