export function toCss(tokens: readonly Token[], options: ToCssOptions = {}): string {
  const { scope = ":root", plugins = [], lean = false, keepTyped = () => false } = options;

  // A custom property registers as a typed `@property` only when its value is concrete (a
  // `var()`/`light-dark()` initial-value is invalid) and — in lean mode — it's explicitly kept typed.
  // Otherwise it becomes a plain declaration. This one policy governs both base tokens and
  // plugin-contributed properties.
  const asProperty = (name: string, value: string): boolean =>
    !isContextual(value) && (!lean || keepTyped(name));

  const properties: PropertyRule[] = [];
  const declarations: [string, string][] = [];
  for (const token of tokens) {
    if (asProperty(token.name, token.value))
      properties.push({ name: token.name, syntax: token.syntax, value: token.value });
    else declarations.push([token.name, token.value]);
  }

  let css = buildCssFile({
    comments: [
      "/* Instructure design tokens + icon set (pantoken) */",
      lean
        ? "/* Lean build: every token is a :root declaration (no @property registrations). */"
        : "/* Concrete tokens are registered with @property; themed/reference tokens are declarations. */",
    ],
    scope,
    properties,
    sections: [{ pairs: declarations }],
  });

  const prepends: string[] = [];
  const appends: string[] = [];
  for (const plugin of checkPlugins(plugins, "css")) {
    const c = plugin.css?.({ tokens: tokens as Token[], css });
    if (!c) continue;
    appendContribution(c, prepends, appends, asProperty);
  }

  return [...prepends, css, ...appends].filter(Boolean).join("\n\n");
}

function appendContribution(
  c: CssContribution,
  prepends: string[],
