30	// node:/postcss/@cssdoc value imports) and needs no codegen: elements get CSS via Vite `?inline` and
31	// `@pantoken/components` *Css() functions, so Vite hot-reloads element `.ts` + co-located `.css` edits
32	// directly. register() is idempotent (it skips already-defined tags), so the barrel's own load-time
33	// register() plus the enhanceApp call below are safe.
34	// Extensionless (this file is type-checked; an explicit `.ts` needs allowImportingTsExtensions). Vite
35	// resolves it to src/index.ts at build/dev time.
36	import { register as registerWebComponents } from "../../../renderers/web-components/src/index";
37	import "@pantoken/demo/demo.css";
38	// `.instui-card` — the shared surface for the in-page CSS-API `@example` previews (`.css-example`) and
39	// the self-hosted demos. A static asset (not generated); the runner iframe loads the same file via ?css=.
40	import "@pantoken/demo/card.css";
41	import "./pantoken.css";
42	import Layout from "./Layout.vue";
43	import { applyTheme, getStoredTheme } from "./theme";
44	
45	export default {
46	  extends: DefaultTheme,
47	  Layout,
48	  enhanceApp(ctx) {
49	    DefaultTheme.enhanceApp?.(ctx);
50	    ctx.app.component("vitepress-mermaid", VitePressMermaid);
51	
52	    // Register the pantoken custom elements so the `@example` blocks on the web-components API pages
53	    // render live (the elements inline their own CSS; the token sheet above colours them). A no-op
54	    // during SSR — it early-returns without a DOM.
55	    registerWebComponents();
56	
57	    // Wire the demo iframes: apply the persisted theme on load, then relay theme + size messages.
58	    if (typeof document !== "undefined") {
59	      // The head script already set the theme attribute (no flash); this reconciles the light/dark
60	      // class and broadcasts the theme to any demos already on the page.
61	      applyTheme(getStoredTheme());
62	
63	      // The runner (inside each figure's iframe) posts the height it wants — its toolbar plus the body
64	      // (which hugs the demo by default, capped at 30rem, or whatever height the reader dragged it to).
65	      // Match the message to its frame by source window and set the height so the iframe mirrors it.
66	      window.addEventListener("message", (event) => {
67	        const data = event.data as { type?: string; height?: number } | null;
68	        // A runner just booted and is asking which theme to render — reply to that frame only.
69	        if (data?.type === "pantoken-demo-request-theme") {
70	          (event.source as Window | null)?.postMessage(
71	            { type: "pantoken-demo-theme", theme: getStoredTheme() },
72	            "*",
73	          );
74	          return;
75	        }
76	        if (data?.type !== "pantoken-demo-size" || typeof data.height !== "number") return;
77	        const frame = [
78	          ...document.querySelectorAll<HTMLIFrameElement>(".pantoken-demo__frame"),
79	        ].find((f) => f.contentWindow === event.source);
80	        if (frame) frame.style.height = `${data.height}px`;
81	      });
82	    }
83	  },
84	} satisfies Theme;
