(() => {
  const alerts = [...document.querySelectorAll('.instui-alert')];
  return alerts.map(a => {
    const after = getComputedStyle(a, '::after');
    const mask = after.maskImage || after.webkitMaskImage || 'none';
    return {
      variant: a.className,
      glyphVar: getComputedStyle(a).getPropertyValue('--pantoken-alert-glyph').trim().slice(0,42),
      afterMaskResolves: mask.startsWith('url(') ? 'yes' : 'NO ('+mask.slice(0,20)+')',
      boxShadow: getComputedStyle(a).boxShadow.slice(0, 30),
    };
  });
})()

